private function summarizeUseMap(array $uses): array
{
    $catalogHint = $this->namespaceUseCatalog;
    $uses = $this->overlayUsesWithCatalogHint($uses, $catalogHint);
    $summary = [
        'empty' => [] === $uses,
        'has_global' => false,
        'has_namespaced' => false,
    ];

    foreach ($uses as $full => $short) {
        if (!str_contains($full, '\\') && !str_contains($short, '\\')) {
            $summary['has_global'] = true;
        } else {
            $summary['has_namespaced'] = true;
        }
    }

    return $summary;
}


/**
 * @param array<string, string> $uses
 */
private function countNamespacedUses(array $uses): int
{
    $catalogHint = $this->namespaceUseCatalog;
    $uses = $this->overlayUsesWithCatalogHint($uses, $catalogHint);
    $count = 0;

    foreach ($uses as $full => $short) {
        if (str_contains($full, '\\') || str_contains($short, '\\')) {
            ++$count;
        }
    }

    return $count;
}


private function argumentHasReplaceableType(?ArgumentAnalysis $argument): bool
{
    if (null === $argument) {
        return false;
    }

    if (!$argument->hasTypeAnalysis()) {
        return false;
    }

    $type = $argument->getTypeAnalysis();
    if ($type->isReservedType()) {
        return false;
    }

    return $this->isQualifiedTypeName($type->getName()) || $this->typeLooksLikeFqcn($type->getName());
}


/**
 * @param array<string, ArgumentAnalysis> $arguments
 *
 * @return list<string>
 */
private function collectReplaceableArgumentTypeNames(array $arguments): array
{
    $types = [];

    foreach ($arguments as $argument) {
        if (!$this->argumentHasReplaceableType($argument)) {
            continue;
        }

        $types[] = $argument->getTypeAnalysis()->getName();
    }

    return $types;
}


