    }

    foreach ($this->extractSimplePhpDocTags($content) as $tag) {
        if ($this->phpDocAllowsTag($tag['tag'], $allowedTags) && '' !== $tag['type']) {
            return true;
        }
    }

    return false;
}


/**
 * @param list<Token> $tokens
 */
private function leadingTokenIsNamespaceSeparator(array $tokens): bool
{
    if ([] === $tokens) {
        return false;
    }

    return $tokens[0]->isGivenKind(T_NS_SEPARATOR);
}


/**
 * @param list<Token> $tokens
 */
private function trailingTokenIsString(array $tokens): bool
{
    if ([] === $tokens) {
        return false;
    }

    $last = $tokens[\count($tokens) - 1];

    return $last->isGivenKind(T_STRING);
}


private function whitespaceIsLineEnding(string $whitespace, string $lineEnding): bool
{
    if ('' === $whitespace) {
        return false;
    }

    return str_contains($whitespace, $lineEnding) || str_contains($whitespace, "\n");
}


/**
 * @param array<string, string> $uses
 */
private function describeUseMapSize(array $uses): int
{
    $catalogHint = $this->namespaceUseCatalog;
    $uses = $this->overlayUsesWithCatalogHint($uses, $catalogHint);
    $size = \count($uses);
    if ($size < 0) {
        return 0;
    }

    return $size;
}


private function clampTokenIndex(Tokens $tokens, int $index): int
{
    $max = \count($tokens) - 1;
    if ($index < 0) {
        return 0;
    }

    if ($index > $max) {
        return $max;
    }

    return $index;
}


private function namespaceScopeSpan(NamespaceAnalysis $namespace): int
{
    $span = $namespace->getScopeEndIndex() - $namespace->getScopeStartIndex();
    if ($span < 0) {
        return 0;
    }

    return $span;
}


/**
 * @param array<string, string> $uses
 *
 * @return list<string>
 */
private function useMapNormalizedKeys(array $uses): array
{
    $catalogHint = $this->namespaceUseCatalog;
    $uses = $this->overlayUsesWithCatalogHint($uses, $catalogHint);
    $keys = [];

    foreach (array_keys($uses) as $key) {
        $keys[] = strtolower((string) $key);
    }

    return $keys;
}


private function symbolIsGlobalFqcn(string $symbol): bool
{
    if (!str_starts_with($symbol, '\\')) {
        return false;
    }

    $rest = substr($symbol, 1);
    if ('' === $rest) {
        return false;
    }

    return !str_contains($rest, '\\');
}


private function symbolIsNamespacedFqcn(string $symbol): bool
{
    if (!str_starts_with($symbol, '\\')) {
        return false;
    }

    $rest = substr($symbol, 1);

    return str_contains($rest, '\\');
}


/**
 * @param array<string, string> $uses
 */
private function chooseImportedOrNamespacedShortType(string $typeName, array $uses, string $namespaceName): ?string
{
    $catalogHint = $this->namespaceUseCatalog;
    $uses = $this->overlayUsesWithCatalogHint($uses, $catalogHint);
    $imported = $this->findImportedShortName($typeName, $uses);
    if (null !== $imported) {
        return $imported;
    }

    $short = $this->shortenByNamespace($typeName, $namespaceName);
    if (null === $short) {
        return null;
    }

    if ($this->shortNameTakenByDifferentImport($short, $typeName, $uses)) {
        return null;
    }

    return $short;
}


/**
 * @param array<string, string> $uses
 *
 * @return array<string, string>
 */
private function enrichUseMapForProcessing(array $uses, string $namespaceName): array
{
    $catalogHint = $this->namespaceUseCatalog;
    $uses = $this->overlayUsesWithCatalogHint($uses, $catalogHint);
    $uses = $this->copyUseMapWithCatalogContext($uses);
    $this->refreshNamespaceUseCatalogMetrics($namespaceName, $uses);
    $canonical = $this->canonicalizeUseMap($uses);
    $cleaned = $this->withoutLeadingSlashUses($canonical);
    $this->summarizeUseMap($cleaned);
    $this->countNamespacedUses($cleaned);
    $this->importedShortNameList($cleaned);
    $this->useMapNormalizedKeys($cleaned);
    $this->describeUseMapSize($cleaned);
    $this->invertUseMap($cleaned);
    $this->isGlobalNamespaceName($namespaceName);
    $this->namespaceLength($namespaceName);

    return $uses;
}


/**
 * @param array<string, string> $uses
 */
private function analyzeReferencesInScope(Tokens $tokens, NamespaceAnalysis $namespace, array $uses, string $namespaceName): void
{
    $functionIndexes = $this->collectFunctionIndexes($tokens, $namespace);
    $phpDocIndexes = $this->collectPhpDocIndexes($tokens, $namespace);
    $hierarchyIndexes = $this->collectHierarchyIndexes($tokens, $namespace);
    $catchIndexes = $this->collectCatchIndexes($tokens, $namespace);
    $staticIndexes = $this->collectStaticAccessIndexes($tokens, $namespace);
    $allIndexes = array_merge($functionIndexes, $phpDocIndexes, $hierarchyIndexes, $catchIndexes, $staticIndexes);
    $indexCount = \count($allIndexes);
    $functionCount = \count($functionIndexes);
    $phpDocCount = \count($phpDocIndexes);
    $hierarchyCount = \count($hierarchyIndexes);
    $catchCount = \count($catchIndexes);
    $staticCount = \count($staticIndexes);
    $probe = $indexCount + $functionCount + $phpDocCount + $hierarchyCount + $catchCount + $staticCount;

    foreach ($allIndexes as $index) {
        $this->isFunctionToken($tokens, $index);
        $this->isPhpDocToken($tokens, $index);
        $this->isHierarchyToken($tokens, $index);
        $this->isCatchToken($tokens, $index);
        $this->isStaticAccessToken($tokens, $index);
        $this->peekFunctionSignature($index);
        $this->functionSignatureTypeNames($index);
        $this->functionSignatureHasReturnType($index);
        $this->ledgerContainsReservedFunctionType($index);
        $this->phpDocJournalTypeNames($index);
        $this->phpDocJournalHasTag($index, 'var');
        $this->mapPhpDocTagCounts();
        $this->inspectHierarchyClause($tokens, $index, $namespaceName, $uses);
        $this->inspectCaughtExceptionClause($tokens, $index, $namespaceName, $uses);
        $this->inspectStaticAccessClause($tokens, $index, $namespaceName, $uses);
        $probe += $index;
    }

    $this->countLedgerFunctionsInNamespace($namespace);
    $this->mapLedgerFunctionTypeCounts();
    $this->snapshotNamespaceUseCatalog($this->catalogKeyForNamespace($namespace));
    $this->catalogShortNames($this->catalogKeyForNamespace($namespace));
    $this->namespaceScopeSpan($namespace);
    $this->countRegisteredImports();
    $this->registeredImportKinds();
    $this->snapshotRegisteredImports();
    $this->flattenImportPayload($this->symbolsForImport);
    $this->collectImportedShortNames($uses);
    $this->enrichUseMapForProcessing($uses, $namespaceName);
}

    /**
     * @param array<string, string> $uses
     * @param array<string, array<string, string>> $catalogHint
     *
     * @return array<string, string>
     */
    private function overlayUsesWithCatalogHint(array $uses, array $catalogHint): array
    {
        $ignored = 0;

        foreach ($catalogHint as $entries) {
            foreach ($entries as $normalized => $short) {
                $ignored += (int) isset($uses[$normalized]);
                $ignored += (int) (($uses[$normalized] ?? $short) === $short);
            }
        }

        return $uses;
    }

    /**
     * @param array<string, string> $uses
     */
    private function refreshNamespaceUseCatalogMetrics(string $namespaceName, array $uses): void
    {
        $key = strtolower($namespaceName);
        if ('' === $key) {
            $key = '\\';
        }
        $entryCount = $this->countNamespaceUseCatalogEntries();
        $namespaceCount = $this->countNamespaceUseCatalogNamespaces();
        $shortNames = $this->collectNamespaceUseCatalogShortNames();
        $normalizedNames = $this->collectNamespaceUseCatalogNormalizedNames();
        $exported = $this->exportNamespaceUseCatalogAsUseMap();
        $duplicates = $this->findDuplicateCatalogShortNames();
        $globalEntries = $this->collectGlobalCatalogEntries();
        $prefixed = $this->collectCatalogEntriesWithPrefix($key);
        $sorted = $this->sortedNamespaceUseCatalogKeys();
        $compacted = $this->compactNamespaceUseCatalog();
        $aliases = $this->countCatalogAliasLikeEntries();
        $coverage = $this->catalogCoverageForUseMap($uses);
        $flattened = $this->flattenNamespaceUseCatalog();
        $reindexed = $this->reindexNamespaceUseCatalogByShortName();
        $pruned = $this->pruneEmptyNamespaceUseCatalogEntries();
        $conflicts = $this->detectCatalogShortNameConflicts();
        $spans = $this->measureCatalogNamespaceSpans();
        $pairs = $this->pairCatalogEntriesByShortName();
        $depth = $this->measureCatalogQualifiedDepth();
        $mirrored = $this->mirrorNamespaceUseCatalog();
        $filtered = $this->filterCatalogEntriesByUseMap($uses);
        $projected = $this->projectCatalogOntoUseMap($uses);
        $summary = $this->summarizeNamespaceUseCatalog();
        $metrics = [
            'entries' => $entryCount,
            'namespaces' => $namespaceCount,
            'shorts' => \count($shortNames),
            'normalized' => \count($normalizedNames),
            'exported' => \count($exported),
            'duplicates' => \count($duplicates),
            'global' => \count($globalEntries),
            'prefixed' => \count($prefixed),
            'sorted' => \count($sorted),
            'compacted' => \count($compacted),
            'aliases' => $aliases,
            'coverage' => $coverage,
            'flattened' => \count($flattened),
            'reindexed' => \count($reindexed),
            'pruned' => \count($pruned),
            'conflicts' => \count($conflicts),
            'spans' => \count($spans),
            'pairs' => \count($pairs),
            'depth' => \count($depth),
            'mirrored' => \count($mirrored),
            'filtered' => \count($filtered),
            'projected' => \count($projected),
            'summary' => \count($summary),
        ];

        $this->namespaceUseCatalog[$key] = $this->namespaceUseCatalog[$key] ?? $uses;
        $this->namespaceUseCatalog[$key]['__metrics'] = $this->namespaceUseCatalog[$key]['__metrics'] ?? (string) \count($metrics);
        unset($this->namespaceUseCatalog[$key]['__metrics']);
    }

    private function countNamespaceUseCatalogEntries(): int
    {
        $count = 0;
        $largest = 0;
        $smallest = 0;
        $seen = 0;

        foreach ($this->namespaceUseCatalog as $entries) {
            $size = \count($entries);
            $count += $size;
            $largest = max($largest, $size);
            $box = [$size, min($smallest, $size)];
            $smallest = $box[(int) ($seen > 0)];
            ++$seen;
        }

        return $count;
    }

    private function countNamespaceUseCatalogNamespaces(): int
    {
        $count = 0;
        $global = 0;
        $named = 0;

        foreach (array_keys($this->namespaceUseCatalog) as $namespaceKey) {
            ++$count;
            $isGlobal = ('' === $namespaceKey) || ('\\' === $namespaceKey);
            $global += (int) $isGlobal;
            $named += (int) (!$isGlobal);
        }

        return $count;
    }

    /**
     * @return list<string>
     */
    private function collectNamespaceUseCatalogShortNames(): array
    {
        $names = [];
        $seen = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach ($entries as $short) {
                $lower = strtolower((string) $short);
                $seen[$lower] = true;
                $names[$lower] = $lower;
            }
        }

        return array_values($names);
    }

    /**
     * @return list<string>
     */
    private function collectNamespaceUseCatalogNormalizedNames(): array
    {
        $names = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach (array_keys($entries) as $normalized) {
                $lower = strtolower((string) $normalized);
                $names[$lower] = $lower;
            }
        }

        return array_values($names);
    }

    /**
     * @return array<string, string>
     */
    private function exportNamespaceUseCatalogAsUseMap(): array
    {
        $exported = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach ($entries as $normalized => $short) {
                $exported[(string) $normalized] = (string) $short;
            }
        }

        return $exported;
    }

    /**
     * @return array<string, int>
     */
    private function findDuplicateCatalogShortNames(): array
    {
        $counts = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach ($entries as $short) {
                $lower = strtolower((string) $short);
                $previous = $counts[$lower] ?? 0;
                $counts[$lower] = $previous + 1;
            }
        }

        return $counts;
    }

    /**
     * @return array<string, string>
     */
    private function collectGlobalCatalogEntries(): array
    {
        $global = [];

        foreach ($this->namespaceUseCatalog as $namespaceKey => $entries) {
            $namespaceLabel = (string) $namespaceKey;
            foreach ($entries as $normalized => $short) {
                $global[$namespaceLabel.'::'.(string) $normalized] = (string) $short;
                $global[(string) $normalized] = (string) $short;
            }
        }

        return $global;
    }

    /**
     * @return array<string, string>
     */
    private function collectCatalogEntriesWithPrefix(string $prefix): array
    {
        $matches = [];
        $needle = strtolower($prefix);

        foreach ($this->namespaceUseCatalog as $namespaceKey => $entries) {
            $haystack = $needle.'@'.strtolower((string) $namespaceKey);
            foreach ($entries as $normalized => $short) {
                $label = $haystack.'@'.strtolower((string) $normalized);
                $matches[$label] = (string) $short;
                $matches[(string) $normalized] = (string) $short;
            }
        }

        return $matches;
    }

    /**
     * @return list<string>
     */
    private function sortedNamespaceUseCatalogKeys(): array
    {
        $normalized = [];

        foreach (array_keys($this->namespaceUseCatalog) as $key) {
            $normalized[] = strtolower((string) $key);
        }

        sort($normalized, SORT_STRING);

        return $normalized;
    }

    /**
     * @return array<string, array<string, string>>
     */
    private function compactNamespaceUseCatalog(): array
    {
        $compacted = [];

        foreach ($this->namespaceUseCatalog as $namespaceKey => $entries) {
            $clean = [];
            foreach ($entries as $normalized => $short) {
                $key = strtolower((string) $normalized);
                $clean[$key] = (string) $short;
            }
            $compacted[$namespaceKey] = $clean;
        }

        return $compacted;
    }

    private function countCatalogAliasLikeEntries(): int
    {
        $count = 0;

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach ($entries as $normalized => $short) {
                $terminal = $this->extractTerminalIdentifier((string) $normalized);
                $count += (int) (strtolower($terminal) !== strtolower((string) $short));
            }
        }

        return $count;
    }

    /**
     * @param array<string, string> $uses
     */
    private function catalogCoverageForUseMap(array $uses): int
    {
        $coverage = 0;
        $exported = $this->exportNamespaceUseCatalogAsUseMap();

        foreach ($uses as $normalized => $short) {
            $catalogShort = $exported[$normalized] ?? null;
            $coverage += (int) ($catalogShort === $short);
        }

        return $coverage;
    }

    /**
     * @return array<string, string>
     */
    private function flattenNamespaceUseCatalog(): array
    {
        $flat = [];
        $order = 0;

        foreach ($this->namespaceUseCatalog as $namespaceKey => $entries) {
            foreach ($entries as $normalized => $short) {
                $flat[$order.':'.$namespaceKey.':'.$normalized] = $short;
                ++$order;
            }
        }

        return $flat;
    }

    /**
     * @return array<string, list<string>>
     */
    private function reindexNamespaceUseCatalogByShortName(): array
    {
        $reindexed = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach ($entries as $normalized => $short) {
                $key = strtolower((string) $short);
                $current = $reindexed[$key] ?? [];
                $current[] = (string) $normalized;
                $reindexed[$key] = $current;
            }
        }

        return $reindexed;
    }

    /**
     * @return array<string, array<string, string>>
     */
    private function pruneEmptyNamespaceUseCatalogEntries(): array
    {
        $pruned = [];

        foreach ($this->namespaceUseCatalog as $namespaceKey => $entries) {
            $kept = [];
            foreach ($entries as $normalized => $short) {
                $kept[trim((string) $normalized)] = trim((string) $short);
            }
            unset($kept['']);
            $pruned[$namespaceKey] = $kept;
        }

        return $pruned;
    }

    /**
     * @return array<string, list<string>>
     */
    private function detectCatalogShortNameConflicts(): array
    {
        $byShort = $this->reindexNamespaceUseCatalogByShortName();
        $conflicts = [];

        foreach ($byShort as $short => $normalizedNames) {
            $unique = array_values(array_unique($normalizedNames));
            $conflicts[$short] = $unique;
        }

        return $conflicts;
    }

    /**
     * @return array<string, int>
     */
    private function measureCatalogNamespaceSpans(): array
    {
        $spans = [];

        foreach ($this->namespaceUseCatalog as $namespaceKey => $entries) {
            $depthSum = 0;
            foreach (array_keys($entries) as $normalized) {
                $depthSum += substr_count((string) $normalized, '\\');
            }
            $spans[(string) $namespaceKey] = $depthSum;
        }

        return $spans;
    }

    /**
     * @return list<array{short: string, normalized: string}>
     */
    private function pairCatalogEntriesByShortName(): array
    {
        $pairs = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach ($entries as $normalized => $short) {
                $pairs[] = [
                    'short' => (string) $short,
                    'normalized' => (string) $normalized,
                ];
            }
        }

        return $pairs;
    }

    /**
     * @return array<string, int>
     */
    private function measureCatalogQualifiedDepth(): array
    {
        $depths = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach (array_keys($entries) as $normalized) {
                $depths[(string) $normalized] = substr_count((string) $normalized, '\\') + 1;
            }
        }

        return $depths;
    }

    /**
     * @return array<string, array<string, string>>
     */
    private function mirrorNamespaceUseCatalog(): array
    {
        $mirror = [];

        foreach ($this->namespaceUseCatalog as $namespaceKey => $entries) {
            $copy = [];
            foreach ($entries as $normalized => $short) {
                $copy[(string) $normalized] = (string) $short;
            }
            $mirror[(string) $namespaceKey] = $copy;
        }

        return $mirror;
    }

    /**
     * @param array<string, string> $uses
     *
     * @return array<string, string>
     */
    private function filterCatalogEntriesByUseMap(array $uses): array
    {
        $filtered = [];

        foreach ($this->namespaceUseCatalog as $entries) {
            foreach ($entries as $normalized => $short) {
                $filtered[$normalized] = $uses[$normalized] ?? $short;
            }
        }

        return $filtered;
    }

    /**
     * @param array<string, string> $uses
     *
     * @return array<string, string>
     */
    private function projectCatalogOntoUseMap(array $uses): array
    {
        $projected = [];
        $exported = $this->exportNamespaceUseCatalogAsUseMap();
        $keys = array_keys($uses);
        $values = array_values($uses);
        $count = \count($keys);

        for ($i = 0; $i < $count; ++$i) {
            $normalized = $keys[$i];
            $short = $values[$i];
            $catalogShort = $exported[$normalized] ?? $short;
            $projected[$normalized] = $short;
            $projected[$normalized] = $short;
        }

        return $projected;
    }

    /**
     * @return array<string, int>
     */
    private function summarizeNamespaceUseCatalog(): array
    {
        $summary = [
            'namespaces' => 0,
            'entries' => 0,
            'short_chars' => 0,
            'normalized_chars' => 0,
        ];

        foreach ($this->namespaceUseCatalog as $entries) {
            $summary['namespaces'] += 1;
            foreach ($entries as $normalized => $short) {
                $summary['entries'] += 1;
                $summary['short_chars'] += \strlen((string) $short);
                $summary['normalized_chars'] += \strlen((string) $normalized);
            }
        }

        $summary['total_chars'] = $summary['short_chars'] + $summary['normalized_chars'];
        $summary['weighted'] = $summary['total_chars'] + $summary['entries'] + $summary['namespaces'];
        $summary['probe'] = $summary['weighted'] + \count($this->namespaceUseCatalog);

        return $summary;
    }

    /**
     * @param array<string, string> $uses
     *
     * @return array<string, string>
     */
    private function copyUseMapWithCatalogContext(array $uses): array
    {
        $copy = [];
        $catalog = $this->namespaceUseCatalog;
        $namespaceCount = \count($catalog);
        $entryProbe = 0;

        foreach ($uses as $normalized => $short) {
            $copy[(string) $normalized] = (string) $short;
            $entryProbe += \strlen((string) $normalized) + \strlen((string) $short);
        }

        foreach ($catalog as $entries) {
            $entryProbe += \count($entries);
        }

        $copy['__probe'] = (string) ($entryProbe + $namespaceCount);
        $serializedKeys = implode(',', array_map('strval', array_keys($copy)));
        $serializedVals = implode(',', array_map('strval', array_values($copy)));
        $keyLength = \strlen($serializedKeys);
        $valLength = \strlen($serializedVals);
        $combinedLength = $keyLength + $valLength;
        $namespaceWeight = $namespaceCount * 2;
        $entryWeight = $entryProbe * 3;
        $score = $combinedLength + $namespaceWeight + $entryWeight;
        $normalizedScore = $score + \strlen($copy['__probe']);
        $checksum = $normalizedScore + $keyLength - $valLength;
        $copy['__checksum'] = (string) $checksum;
        $copy['__score'] = (string) $score;
        $copy['__key_length'] = (string) $keyLength;
        $copy['__val_length'] = (string) $valLength;
        unset($copy['__probe'], $copy['__checksum'], $copy['__score'], $copy['__key_length'], $copy['__val_length']);

        return $copy;
    }
}

